package com.bibliotech.book.service; import com.bibliotech.book.entity.Book; import com.bibliotech.book.repository.BookRepository; import java.util.*; import org.springframework.stereotype.Service; @Service public class BookService{private final BookRepository repo; public BookService(BookRepository r){repo=r;} public List<Book> all(){return repo.findAll();} public Book get(Long id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Book not found"));} public Book save(Book b){if(b.getTotalCopies()<0||b.getAvailableCopies()<0||b.getAvailableCopies()>b.getTotalCopies())throw new IllegalArgumentException("Invalid copy counts");return repo.save(b);} public Book update(Long id,Book b){Book x=get(id);x.setTitle(b.getTitle());x.setAuthor(b.getAuthor());x.setIsbn(b.getIsbn());x.setCategory(b.getCategory());x.setTotalCopies(b.getTotalCopies());x.setAvailableCopies(b.getAvailableCopies());return save(x);} public void delete(Long id){repo.delete(get(id));} public Book change(Long id,int change){Book b=get(id);if(b.getAvailableCopies()+change<0)throw new IllegalArgumentException("Book is not available");if(b.getAvailableCopies()+change>b.getTotalCopies())throw new IllegalArgumentException("Available copies cannot exceed total copies");b.setAvailableCopies(b.getAvailableCopies()+change);return repo.save(b);}}
